-- ============================================================
-- استيراد عاملات روزانا (321 عاملة) إلى public.workers
-- مُولّد آلياً بواسطة scripts/generate-rozana-import.py
-- يُشغَّل يدوياً في Supabase Dashboard → SQL Editor.
-- آمن لإعادة التشغيل (idempotent).
-- ============================================================

-- 1) ضمان أن employment_type مصفوفة text[] (migration 0003 مكافئ).
--    يتجاهل التحويل إن كان العمود أصلاً مصفوفة.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'workers'
      and column_name = 'employment_type' and udt_name = 'text'
  ) then
    alter table public.workers alter column employment_type drop default;
    alter table public.workers alter column employment_type drop not null;
    alter table public.workers
      alter column employment_type type text[] using array[employment_type];
    alter table public.workers alter column employment_type set default '{}';
  end if;
end $$;

-- 2) حذف العاملات الوهمية التجريبية الحالية.
--    bookings مرتبطة بـ worker_id مع on delete cascade فتُحذف تلقائياً.
delete from public.workers;

-- 3) إدراج عاملات روزانا على دفعات (50 صف لكل إدراج) لتفادي حدود الجلسة.
--    on conflict (slug) do nothing → إعادة التشغيل آمنة.

-- الدفعة 1: الصفوف 001–050
on conflict (slug) do nothing;

-- الدفعة 2: الصفوف 051–100
on conflict (slug) do nothing;

-- الدفعة 3: الصفوف 101–150
on conflict (slug) do nothing;

-- الدفعة 4: الصفوف 151–200
on conflict (slug) do nothing;

-- الدفعة 5: الصفوف 201–250
on conflict (slug) do nothing;

-- الدفعة 6: الصفوف 251–300
on conflict (slug) do nothing;

-- الدفعة 7: الصفوف 301–321
on conflict (slug) do nothing;

-- 4) التحقق من العدد النهائي.
select count(*) as total_workers from public.workers;
